//! Bounded native evaluator for the benchmark's generated reserve function.
//! RustPython supplies parsing only. No Python VM, imports, I/O, or subprocess.
use super::*;
use rustpython_parser::{ast,Parse};
use rustpython_ast::Visitor;
#[derive(Default)]struct Safety{error:Option<&'static str>}
impl Visitor for Safety{fn visit_stmt(&mut self,node:ast::Stmt){if matches!(&node,ast::Stmt::Import(_)|ast::Stmt::ImportFrom(_)|ast::Stmt::Global(_)|ast::Stmt::Nonlocal(_)|ast::Stmt::With(_)|ast::Stmt::AsyncWith(_)|ast::Stmt::ClassDef(_)){self.error=Some("patched_source_unsafe_ast");}self.generic_visit_stmt(node)}fn visit_expr(&mut self,node:ast::Expr){if matches!(&node,ast::Expr::Attribute(_)|ast::Expr::Lambda(_)){self.error=Some("patched_source_unsafe_ast");}if let ast::Expr::Call(c)=&node{if !matches!(c.func.as_ref(),ast::Expr::Name(n)if ["ValueError","TypeError","isinstance"].contains(&n.id.as_str()))&&self.error.is_none(){self.error=Some("patched_source_unsafe_call")}}self.generic_visit_expr(node)}}
type Eval<T>=std::result::Result<T,&'static str>;
enum Flow{Next,Return(Value),Break,Continue}
struct Machine{env:BTreeMap<String,Value>,steps:usize}
impl Machine{fn step(&mut self)->Eval<()>{self.steps+=1;if self.steps>10000{Err("ExecutionLimitError")}else{Ok(())}}
fn expr(&mut self,e:&ast::Expr)->Eval<Value>{self.step()?;match e{
ast::Expr::Constant(c)=>match &c.value{ast::Constant::None=>Ok(Value::Null),ast::Constant::Bool(b)=>Ok(json!(b)),ast::Constant::Str(s)=>Ok(json!(s)),ast::Constant::Int(n)=>n.to_string().parse::<i64>().map(|n|json!(n)).map_err(|_|"OverflowError"),ast::Constant::Float(n)=>Ok(json!(n)),_=>Err("NotImplementedError")},
ast::Expr::Name(n)=>self.env.get(n.id.as_str()).cloned().ok_or("NameError"),
ast::Expr::Dict(d)=>{let mut out=serde_json::Map::new();for(k,v)in d.keys.iter().zip(&d.values){let v=self.expr(v)?;if let Some(k)=k{let key=self.expr(k)?;let key=key.as_str().ok_or("TypeError")?;out.insert(key.into(),v);}else{out.extend(v.as_object().ok_or("TypeError")?.clone());}}Ok(Value::Object(out))},
ast::Expr::List(a)=>Ok(json!(a.elts.iter().map(|v|self.expr(v)).collect::<Eval<Vec<_>>>()?)),ast::Expr::Tuple(a)=>Ok(json!(a.elts.iter().map(|v|self.expr(v)).collect::<Eval<Vec<_>>>()?)),
ast::Expr::IfExp(e)=>{let condition=self.expr(&e.test)?;self.expr(if truthy(&condition){&e.body}else{&e.orelse})},
ast::Expr::BoolOp(e)=>{let mut result=Value::Null;for v in &e.values{result=self.expr(v)?;match e.op{ast::BoolOp::And if !truthy(&result)=>break,ast::BoolOp::Or if truthy(&result)=>break,_=>{}}}Ok(result)},
ast::Expr::UnaryOp(e)=>{let v=self.expr(&e.operand)?;match e.op{ast::UnaryOp::Not=>Ok(json!(!truthy(&v))),ast::UnaryOp::USub=>integer_value(&v)?.checked_neg().map(|n|json!(n)).ok_or("OverflowError"),ast::UnaryOp::UAdd=>Ok(json!(integer_value(&v)?)),ast::UnaryOp::Invert=>Ok(json!(!integer_value(&v)?))}},
ast::Expr::BinOp(e)=>{let l=self.expr(&e.left)?;let r=self.expr(&e.right)?;binary(&l,&e.op,&r)},
ast::Expr::Compare(e)=>{let mut l=self.expr(&e.left)?;for(op,right)in e.ops.iter().zip(&e.comparators){let r=self.expr(right)?;if !compare(&l,op,&r)?{return Ok(json!(false))}l=r;}Ok(json!(true))},
ast::Expr::NamedExpr(e)=>{let value=self.expr(&e.value)?;self.assign(&e.target,&value)?;Ok(value)},
ast::Expr::Subscript(e)=>{let value=self.expr(&e.value)?;let index=self.expr(&e.slice)?;if let Some(o)=value.as_object(){o.get(index.as_str().ok_or("TypeError")?).cloned().ok_or("KeyError")}else if let Some(a)=value.as_array(){let mut n=integer_value(&index)?;if n<0{n+=a.len()as i64}usize::try_from(n).ok().and_then(|i|a.get(i)).cloned().ok_or("IndexError")}else{Err("TypeError")}},
ast::Expr::Call(c)=>{let ast::Expr::Name(name)=c.func.as_ref()else{return Err("TypeError")};if name.id.as_str()=="isinstance"{if c.args.len()!=2||!c.keywords.is_empty(){return Err("TypeError")}let value=self.expr(&c.args[0])?;fn test(value:&Value,kind:&ast::Expr)->Eval<bool>{match kind{ast::Expr::Name(n)=>match n.id.as_str(){"int"=>Ok(value.is_boolean()||value.as_i64().is_some()||value.as_u64().is_some()),"bool"=>Ok(value.is_boolean()),_=>Err("NameError")},ast::Expr::Tuple(t)=>{for k in &t.elts{if test(value,k)?{return Ok(true)}}Ok(false)},_=>Err("TypeError")}}Ok(json!(test(&value,&c.args[1])?))}else if ["ValueError","TypeError"].contains(&name.id.as_str()){for arg in &c.args{self.expr(arg)?;}Ok(json!({"__exception":name.id.as_str()}))}else{Err("NameError")}},
_=>Err("NotImplementedError")}}
fn assign(&mut self,target:&ast::Expr,value:&Value)->Eval<()>{match target{ast::Expr::Name(n)=>{self.env.insert(n.id.to_string(),value.clone());Ok(())},ast::Expr::Tuple(t)=>{let a=value.as_array().filter(|a|a.len()==t.elts.len()).ok_or("ValueError")?;for(t,v)in t.elts.iter().zip(a){self.assign(t,v)?}Ok(())},ast::Expr::List(t)=>{let a=value.as_array().filter(|a|a.len()==t.elts.len()).ok_or("ValueError")?;for(t,v)in t.elts.iter().zip(a){self.assign(t,v)?}Ok(())},_=>Err("NotImplementedError")}}
fn block(&mut self,body:&[ast::Stmt])->Eval<Flow>{for s in body{self.step()?;let flow=match s{ast::Stmt::Return(s)=>Flow::Return(match &s.value{Some(e)=>self.expr(e)?,None=>Value::Null}),ast::Stmt::Assign(s)=>{let v=self.expr(&s.value)?;for target in &s.targets{self.assign(target,&v)?}Flow::Next},ast::Stmt::AnnAssign(s)=>{if let Some(e)=&s.value{let v=self.expr(e)?;self.assign(&s.target,&v)?}Flow::Next},ast::Stmt::AugAssign(s)=>{let left=self.expr(&s.target)?;let right=self.expr(&s.value)?;let value=binary(&left,&s.op,&right)?;self.assign(&s.target,&value)?;Flow::Next},ast::Stmt::If(s)=>{let test=self.expr(&s.test)?;self.block(if truthy(&test){&s.body}else{&s.orelse})?},ast::Stmt::While(s)=>{let mut broke=false;loop{let test=self.expr(&s.test)?;if !truthy(&test){break}match self.block(&s.body)?{Flow::Break=>{broke=true;break},Flow::Return(v)=>return Ok(Flow::Return(v)),_=>{}}}if !broke{self.block(&s.orelse)?}else{Flow::Next}},ast::Stmt::For(s)=>{let iter=self.expr(&s.iter)?;let a=iter.as_array().ok_or("TypeError")?;let mut broke=false;for v in a{self.assign(&s.target,v)?;match self.block(&s.body)?{Flow::Break=>{broke=true;break},Flow::Return(v)=>return Ok(Flow::Return(v)),_=>{}}}if !broke{self.block(&s.orelse)?}else{Flow::Next}},ast::Stmt::Raise(s)=>{let error=match &s.exc{Some(e)=>match e.as_ref(){ast::Expr::Name(n)if n.id.as_str()=="ValueError"=>"ValueError",ast::Expr::Name(n)if n.id.as_str()=="TypeError"=>"TypeError",_=>{let v=self.expr(e)?;match text(&v["__exception"]){"ValueError"=>"ValueError","TypeError"=>"TypeError",_=>"TypeError"}}},None=>"RuntimeError"};return Err(error)},ast::Stmt::Assert(s)=>{let v=self.expr(&s.test)?;if !truthy(&v){return Err("AssertionError")}Flow::Next},ast::Stmt::Expr(s)=>{self.expr(&s.value)?;Flow::Next},ast::Stmt::Pass(_)=>Flow::Next,ast::Stmt::Break(_)=>Flow::Break,ast::Stmt::Continue(_)=>Flow::Continue,_=>return Err("NotImplementedError")};if !matches!(flow,Flow::Next){return Ok(flow)}}Ok(Flow::Next)}
}
fn integer_value(v:&Value)->Eval<i64>{if let Some(b)=v.as_bool(){Ok(i64::from(b))}else{v.as_i64().ok_or("TypeError")}}
fn binary(l:&Value,op:&ast::Operator,r:&Value)->Eval<Value>{if let(ast::Operator::Add,Some(a),Some(b))=(op,l.as_str(),r.as_str()){if a.len()+b.len()>65536{return Err("ExecutionLimitError")}return Ok(json!(format!("{a}{b}")))}let(a,b)=(integer_value(l)?,integer_value(r)?);let out=match op{ast::Operator::Add=>a.checked_add(b),ast::Operator::Sub=>a.checked_sub(b),ast::Operator::Mult=>a.checked_mul(b),ast::Operator::FloorDiv=>{if b==0{return Err("ZeroDivisionError")}a.checked_div_euclid(b)},ast::Operator::Mod=>{if b==0{return Err("ZeroDivisionError")}a.checked_rem_euclid(b)},ast::Operator::Div=>{if b==0{return Err("ZeroDivisionError")}return Ok(json!(a as f64/b as f64))},ast::Operator::Pow=>u32::try_from(b).ok().filter(|b|*b<=64).and_then(|b|a.checked_pow(b)),ast::Operator::BitAnd=>Some(a&b),ast::Operator::BitOr=>Some(a|b),ast::Operator::BitXor=>Some(a^b),ast::Operator::LShift=>u32::try_from(b).ok().and_then(|b|a.checked_shl(b)),ast::Operator::RShift=>u32::try_from(b).ok().and_then(|b|a.checked_shr(b)),_=>return Err("NotImplementedError")};out.map(|v|json!(v)).ok_or("OverflowError")}
fn compare(l:&Value,op:&ast::CmpOp,r:&Value)->Eval<bool>{let equal=if let(Ok(a),Ok(b))=(integer_value(l),integer_value(r)){a==b}else{l==r};Ok(match op{ast::CmpOp::Eq=>equal,ast::CmpOp::NotEq=>!equal,ast::CmpOp::Is=>l==r,ast::CmpOp::IsNot=>l!=r,ast::CmpOp::Lt=>integer_value(l)?<integer_value(r)?,ast::CmpOp::LtE=>integer_value(l)?<=integer_value(r)?,ast::CmpOp::Gt=>integer_value(l)?>integer_value(r)?,ast::CmpOp::GtE=>integer_value(l)?>=integer_value(r)?,ast::CmpOp::In|ast::CmpOp::NotIn=>{let has=if let Some(a)=r.as_array(){a.contains(l)}else if let Some(o)=r.as_object(){o.contains_key(l.as_str().ok_or("TypeError")?)}else if let Some(s)=r.as_str(){s.contains(l.as_str().ok_or("TypeError")?)}else{return Err("TypeError")};if matches!(op,ast::CmpOp::NotIn){!has}else{has}}})}
fn call(function:&ast::StmtFunctionDef,stock:&Value,requested:&Value)->Eval<Value>{if !function.decorator_list.is_empty(){return Err("TypeError")}let args:Vec<_>=function.args.posonlyargs.iter().chain(&function.args.args).collect();let mut machine=Machine{env:BTreeMap::new(),steps:0};if args.len()<2&&function.args.vararg.is_none(){return Err("TypeError")}for(i,arg)in args.iter().enumerate(){let value=match i{0=>stock.clone(),1=>requested.clone(),_=>match &arg.default{Some(e)=>machine.expr(e)?,None=>return Err("TypeError")}};machine.env.insert(arg.def.arg.to_string(),value);}if let Some(arg)=&function.args.vararg{let values=if args.len()==0{vec![stock.clone(),requested.clone()]}else if args.len()==1{vec![requested.clone()]}else{vec![]};machine.env.insert(arg.arg.to_string(),json!(values));}for arg in &function.args.kwonlyargs{let e=arg.default.as_ref().ok_or("TypeError")?;let value=machine.expr(e)?;machine.env.insert(arg.def.arg.to_string(),value);}match machine.block(&function.body)?{Flow::Return(v)=>Ok(v),_=>Ok(Value::Null)}}
pub fn validate(value:&Value,expected:&Value)->(bool,String){let fail=|s:&str|(false,s.to_owned());if !value.as_object().is_some_and(|o|o.len()==1&&o.contains_key("patched_source"))||!value["patched_source"].is_string(){return fail("patched_source_contract")}let source=text(&value["patched_source"]);if source.len()>4096{return fail("patched_source_too_large")}let tree=match ast::Suite::parse(source,"<candidate-reserve>"){Ok(v)=>v,Err(_)=>return fail("patched_source_syntax")};if tree.len()!=1||!matches!(&tree[0],ast::Stmt::FunctionDef(_)|ast::Stmt::AsyncFunctionDef(_)){return fail("patched_source_must_define_one_function")}let ast::Stmt::FunctionDef(function)=&tree[0]else{return fail("patched_source_function_name")};if function.name.as_str()!="reserve"{return fail("patched_source_function_name")}let mut safety=Safety::default();for s in tree.iter().cloned(){safety.visit_stmt(s)}if let Some(error)=safety.error{return fail(error)}for case in expected["required_cases"].as_array().into_iter().flatten(){let result=call(function,&case[0],&case[1]);match result{Ok(value)if python_equal(&value,&json!({"accepted":case[2],"remaining":case[3]}))=>{},Ok(_)=>return fail(&format!("reserve_case_failed:{}:{}",case[0],case[1])),Err(error)=>return fail(&format!("patched_source_runtime:{error}"))}}match call(function,&json!(5),&json!(-1)){Err("ValueError")=>(true,"passed".into()),Err(error)=>fail(&format!("patched_source_runtime:{error}")),Ok(_)=>fail("negative_request_not_rejected")}}
#[cfg(test)]mod tests{use super::*;fn expected()->Value{json!({"required_cases":[[5,2,true,3],[5,5,true,0],[5,6,false,5],[0,0,true,0]]})}#[test]fn bounded_native_reserve_executes_expected_contract(){let s="def reserve(stock, requested):\n    if requested < 0:\n        raise ValueError('negative')\n    if requested <= stock:\n        return {'accepted': True, 'remaining': stock-requested}\n    return {'accepted': False, 'remaining': stock}\n";assert_eq!(validate(&json!({"patched_source":s}),&expected()),(true,"passed".into()));}#[test]fn unsafe_call_rejected_without_execution(){assert_eq!(validate(&json!({"patched_source":"def reserve(a,b):\n return open('/etc/passwd')\n"}),&expected()).1,"patched_source_unsafe_call");}#[test]fn infinite_loop_is_bounded(){assert_eq!(validate(&json!({"patched_source":"def reserve(a,b):\n while True: pass\n"}),&expected()).1,"patched_source_runtime:ExecutionLimitError");}}
#[cfg(test)]mod source_contract{use super::*;#[test]fn source_annotated_and_type_guarded_reserve_functions(){for guard in ["","    if not isinstance(requested, int):\n        raise TypeError('integer required')\n"]{let source=format!("def reserve(stock: int, requested: int):\n{guard}    if requested < 0:\n        raise ValueError()\n    accepted = requested <= stock\n    return {{'accepted': accepted, 'remaining': stock-requested if accepted else stock}}\n");let expected=json!({"required_cases":[[5,2,true,3],[5,5,true,0],[5,6,false,5],[0,0,true,0]]});assert_eq!(validate(&json!({"patched_source":source}),&expected),(true,"passed".into()));}assert_eq!(validate(&json!({"patched_source":"import os\ndef reserve(stock: int, requested: int):\n    return {'accepted': True, 'remaining':0}"}),&json!({})).1,"patched_source_must_define_one_function");}}
fn python_equal(a:&Value,b:&Value)->bool{let numeric=|v:&Value|v.as_f64().or_else(||v.as_bool().map(|b|if b{1.0}else{0.0}));if let(Some(a),Some(b))=(numeric(a),numeric(b)){return a==b}match(a,b){(Value::Object(a),Value::Object(b))=>a.len()==b.len()&&a.iter().all(|(k,v)|b.get(k).is_some_and(|w|python_equal(v,w))),(Value::Array(a),Value::Array(b))=>a.len()==b.len()&&a.iter().zip(b).all(|(a,b)|python_equal(a,b)),_=>a==b}}
